#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 3c: thumbnails and video facts
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# The measurement of 8 Oct 2026 showed what this server can do with
# FFmpeg: read a video's facts in under a second and take a picture in
# a few seconds, but not turn a lecture into streams (360p alone ran at
# half playback speed). So this part builds the first two, and leaves
# streams (HLS) for when there is more compute. Videos keep playing
# from the original file, as they do now.
#
# After this part:
#   * every upload gets a thumbnail for its library card and a poster
#     for the player, taken a tenth of the way into the video
#   * every upload gets its facts: length, picture size, frame rate,
#     video format and file type. They show under the title
#   * the server knows whether browsers can play a file as it is. If
#     they cannot (an AVI, HEVC from a phone), the owner is told so in
#     plain words, and the player names the format instead of guessing
#   * FFmpeg reads the original where it lies, through a signed
#     address into the bucket. Nothing is copied to the server, so a
#     10 GB file costs the same as a small one
#   * pictures are as private as their video: an address is only given
#     to someone allowed to open the video. An address stays the same
#     for six hours, so browsers keep the picture
#   * the thumbnail job runs beside transcription. If it fails, the
#     video still plays, is still transcribed, and shows the card it
#     had before thumbnails existed
#   * videos uploaded before this part get their thumbnail in the
#     background, a few at a time, starting 30 seconds after the deploy
#   * a file is only ever opened as a plain video. A playlist or a list
#     of other files saved under a video's name is refused
#   * the measurement itself (/api/health/media and its table) is
#     removed. /api/health now reports the FFmpeg version instead
#
#   BACKEND   2 new files, 9 changed, 1 removed. Database migration
#             006_media runs by itself at startup. No new packages.
#   FRONTEND  1 new file, 7 changed. No new packages.
#
#   ./vm_media.sh            apply (needs Part 3c step 1 on the branch)
#   ./vm_media.sh --force    apply even if local files differ from GitHub
#   ./vm_media.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_media"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_media_backups"

ADD=(
  "backend/src/lib/media.ts"
  "backend/src/services/inspect.ts"
  "frontend/src/lib/media.ts"
)
MOD=(
  "backend/src/index.ts"
  "backend/src/lib/assets.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/lib/storage.ts"
  "backend/src/lib/store.ts"
  "backend/src/lib/uploads.ts"
  "backend/src/routes/videos.ts"
  "backend/src/services/pipeline.ts"
  "backend/src/types/video.ts"
  "frontend/src/app/v/[id]/page.tsx"
  "frontend/src/app/video/[id]/page.tsx"
  "frontend/src/components/video/IntelligenceStrip.tsx"
  "frontend/src/components/video/VideoCard.tsx"
  "frontend/src/components/video/VideoDetails.tsx"
  "frontend/src/components/video/VideoPlayer.tsx"
  "frontend/src/lib/api.ts"
)
DEL=(
  "backend/src/routes/mediaProbe.ts"
)
