verify "$TMPD/a2" "${NEW_ADD[2]}" "frontend/src/lib/media.ts"

grep -q "$MARKER" "$TMPD/a0"                       || die "media.ts payload missing marker. Aborting."
grep -q "$MARKER" "$TMPD/a1"                       || die "inspect.ts payload missing marker. Aborting."
grep -q 'format_whitelist' "$TMPD/a0"              || die "media.ts payload lost the format limit. Aborting."
grep -q '006_media' "$TMPD/m2"                   || die "migrations.ts payload missing migration 006. Aborting."
grep -q '005_video_info' "$TMPD/m2"              || die "migrations.ts payload lost migration 005. Aborting."
grep -q '/api/collections' "$TMPD/m0"            || die "index.ts payload lost the collection routes. Aborting."
grep -q '/api/uploads' "$TMPD/m0"                || die "index.ts payload lost the upload routes. Aborting."
if grep -q 'mediaProbe' "$TMPD/m0"; then die "index.ts payload still mounts the measurement. Aborting."; fi
grep -q 'canView' "$TMPD/m6"                     || die "videos.ts payload lost the private check. Aborting."
grep -q 'requireAuth' "$TMPD/m6"                 || die "videos.ts payload lost sign in. Aborting."
grep -q 'signedUrlStable' "$TMPD/m3"             || die "storage.ts payload missing stable addresses. Aborting."
grep -q 'completeMultipart' "$TMPD/m3"           || die "storage.ts payload lost multipart support. Aborting."
grep -q 'registerHandler("transcribe"' "$TMPD/m7"   || die "pipeline.ts payload lost transcription. Aborting."
grep -q 'ChapterRuler' "$TMPD/m12"               || die "VideoCard.tsx payload lost the chapter ruler. Aborting."
grep -q 'createUpload' "$TMPD/m15"               || die "api.ts payload lost the upload calls. Aborting."
say "19 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}" "${DEL[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
for f in "${DEL[@]}"; do rm -f "$f"; done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
for f in "${DEL[@]}"; do [ ! -f "$f" ] || rollback "Could not remove $f."; done

say "Applied thumbnails and video facts (rebuild Part 3c)."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit) && (cd frontend && npx tsc --noEmit && npm run build)"
say "Undo: ./vm_media.sh --revert"
